# Security Review Feedback for app.js

## Current Issues Identified:

1. **Missing Input Validation:**
   - No validation on incoming request parameters
   - No sanitization of user inputs
   - No protection against injection attacks

2. **Inadequate Error Handling:**
   - No centralized error handling middleware
   - No async error wrapping
   - Generic error responses that might leak sensitive information
   - No validation error handling

3. **Missing Security Headers:**
   - No security-related HTTP headers (Helmet-like protection)
   - No CORS configuration
   - No rate limiting

4. **Information Disclosure Risks:**
   - Detailed error messages could expose internal implementation
   - Stack traces might be visible in production

## Recommended Improvements:

### 1. Add Input Validation Middleware
```javascript
// Add validation for query parameters, body, etc.
// Use libraries like Joi, express-validator, or zod
```

### 2. Implement Comprehensive Error Handling
```javascript
// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => 
  Promise.resolve(fn(req, res, next)).catch(next);

// Central error handler
app.use((err, req, res, next) => {
  console.error(err); // Log for debugging

  // Don't leak stack traces in production
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({
    error: message,
    // Only include details in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});
```

### 3. Add Security Middleware
```javascript
// Helmet for security headers
app.use(helmet());

// Rate limiting
const rateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});
app.use(rateLimiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || '',
  credentials: true
}));
```

### 4. Improve Specific Routes

For the `/users` endpoint:
```javascript
app.get('/users', asyncHandler(async (req, res) => {
  // Validate query parameters if any
  const { limit, offset } = req.query;

  // Add pagination validation
  const parsedLimit = Math.min(parseInt(limit) || 10, 100); // Max 100
  const parsedOffset = Math.max(parseInt(offset) || 0, 0);

  // Simulate fetching users with validation
  const users = [ /* ... */ ];

  res.json({
    users: users.slice(parsedOffset, parsedOffset + parsedLimit),
    pagination: {
      limit: parsedLimit,
      offset: parsedOffset,
      total: users.length
    }
  });
}));
```

### 5. Additional Security Considerations:
- Add request size limits
- Implement proper HTTP method validation
- Add request timeout middleware
- Consider implementing API versioning
- Add request/response logging (being careful not to log sensitive data)
- Use environment-specific configurations

// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { z } = require('zod');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || [] 
    : true, // Allow all origins in development
  credentials: true,
}));

// Request logging (be careful not to log sensitive data in production)
app.use((req, res, next) => {
  if (process.env.NODE_ENV !== 'production') {
    console.log(`${req.method} ${req.path}`);
  }
  next();
});

// Validation schemas
const paginationSchema = z.object({
  limit: z.string().optional().transform(val => val ? parseInt(val) : 10).refine(val => !isNaN(val) && val > 0 && val <= 100, {
    message: "Limit must be a number between 1 and 100"
  }).default(10),
  offset: z.string().optional().transform(val => val ? parseInt(val) : 0).refine(val => !isNaN(val) && val >= 0, {
    message: "Offset must be a non-negative number"
  }).default(0),
});

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => 
  Promise.resolve(fn(req, res, next)).catch(next);

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
}));

// Users endpoint with validation and error handling
app.get('/users', asyncHandler(async (req, res) => {
  // Validate query parameters
  const { limit, offset } = paginationSchema.parse(req.query);

  // Simulated database query with pagination
  const allUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
    { id: 5, name: 'Eve', email: 'eve@example.com' },
  ];

  // Apply pagination
  const paginatedUsers = allUsers.slice(offset, offset + limit);

  res.json({
    users: paginatedUsers,
    pagination: {
      limit,
      offset,
      total: allUsers.length,
      hasMore: offset + limit < allUsers.length
    }
  });
}));

// Example POST endpoint with validation
app.post('/users', asyncHandler(async (req, res) => {
  // Define validation schema for user creation
  const userSchema = z.object({
    name: z.string().min(1, "Name is required").max(100, "Name too long"),
    email: z.string().email("Invalid email format"),
  });

  // Validate request body
  const validatedData = userSchema.parse(req.body);

  // Simulate user creation (in real app, this would hit a database)
  const newUser = {
    id: Date.now(), // Simple ID generation for demo
    ...validatedData,
    createdAt: new Date().toISOString()
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
}));

// 404 handler - keep last
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.originalUrl,
    error: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack
  });

  // Handle Zod validation errors
  if (err instanceof z.ZodError) {
    return res.status(400).json({
      error: 'Validation Failed',
      details: err.errors.map(error => ({
        field: error.path.join('.'),
        message: error.message
      }))
    });
  }

  // Handle other known errors with status codes
  const statusCode = err.status || 500;

  // Don't leak internal error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? (statusCode === 500 ? 'Internal Server Error' : err.message) 
    : err.message;

  res.status(statusCode).json({
    error: message,
    // Include additional details only in development
    ...(process.env.NODE_ENV !== 'production' && {
      timestamp: new Date().toISOString(),
      // Only include stack in non-production
      ...(statusCode >= 500 && { stack: err.stack })
    })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throw an error if needed
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

