// Improved application with enhanced error handling, input validation, and security
const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize user input against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Parse URL-encoded bodies

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${new Date().toISOString()}`);
  next();
});

// Input validation middleware for user-related routes
const validateUserQuery = (req, res, next) => {
  // Validate query parameters
  const { limit, offset, search } = req.query;

  if (limit !== undefined) {
    const limitNum = parseInt(limit);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Limit must be a number between 1 and 100'
      });
    }
  }

  if (offset !== undefined) {
    const offsetNum = parseInt(offset);
    if (isNaN(offsetNum) || offsetNum < 0) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Offset must be a non-negative number'
      });
    }
  }

  if (search !== undefined && typeof search !== 'string') {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Search must be a string'
    });
  }

  // Sanitize search input if provided
  if (search && typeof search === 'string') {
    req.query.search = search.trim().substring(0, 50); // Limit length
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve health status'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateUserQuery, (req, res) => {
  try {
    // Simulate database query with validated parameters
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const search = req.query.search;

    // In a real app, this would be a database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Filter users based on search if provided
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      status: 'success',
      data: {
        users: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: filteredUsers.length,
          hasMore: offset + limit < filteredUsers.length
        }
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// POST endpoint for creating users (example)
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string') {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Name is required and must be a string'
      });
    }

    if (!email || typeof email !== 'string') {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Email is required and must be a string'
      });
    }

    // Email format validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Invalid email format'
      });
    }

    // Name length validation
    if (name.trim().length < 2 || name.trim().length > 50) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Name must be between 2 and 50 characters'
      });
    }

    // In a real app, save to database
    const newUser = {
      id: Date.now(), // Simplified ID generation
      name: name.trim(),
      email: email.toLowerCase().trim()
    };

    res.status(201).json({
      status: 'success',
      data: newUser
    });
  } catch (error) {
    console.error('Error in POST /users endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred while creating user'
    });
  }
});

// 404 handler - must be placed after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handling middleware - must be last
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Don't leak stack trace in production
  const response = {
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: err.message || 'An error occurred'
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

