const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded data
app.use(cookieParser());
app.use(logger('dev')); // Request logging

// Prevent NoSQL injection
app.use(mongoSanitize());

// Prevent XSS attacks
app.use(xss());

// Prevent HTTP parameter pollution
app.use(hpp());

// Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// CORS configuration (adjust origins as needed)
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', 'https://your-trusted-domain.com');
  res.header('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE');
  res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

// Validation schemas
const healthCheckSchema = {
  query: Joi.object({
    // Health check typically doesn't need parameters, but validating if any are provided
    detailed: Joi.boolean().optional()
  })
};

const usersSchema = {
  query: Joi.object({
    limit: Joi.number().integer().min(1).max(100).optional(),
    offset: Joi.number().integer().min(0).optional(),
    sort: Joi.string().valid('name', 'email', 'id').optional(),
    order: Joi.string().valid('asc', 'desc').optional()
  })
};

// Routes with proper error handling and validation
app.get('/health', validate(healthCheckSchema), (req, res, next) => {
  try {
    const { detailed } = req.query;

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed) {
      response.memoryUsage = process.memoryUsage();
      response.nodeVersion = process.version;
    }

    res.json(response);
  } catch (error) {
    next(error);
  }
});

app.get('/users', validate(usersSchema), (req, res, next) => {
  try {
    const { limit = 10, offset = 0, sort = 'id', order = 'asc' } = req.query;

    // Simulated database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' }
    ];

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return order === 'asc' ? -1 : 1;
      if (a[sort] > b[sort]) return order === 'asc' ? 1 : -1;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res, next) => {
  next(createError(404, 'Not Found'));
});

// Error handling middleware
app.use((err, req, res, next) => {
  // Set locals, only providing error in development
  res.locals.message = err.message;
  res.locals.error = req.app.get('env') === 'development' ? err : {};

  // Log error for monitoring
  console.error(`[${new Date().toISOString()}] Error:`, err);

  // Determine status code
  const status = err.status || 500;

  // Send error response
  res.status(status).json({
    error: {
      message: err.message,
      // Only include stack in development
      ...(req.app.get('env') === 'development' && { stack: err.stack })
    }
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = { app, server };

