const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS

// Limit JSON body size to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));

// Prevent NoSQL injection
app.use(mongoSanitize());

// Prevent XSS attacks
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  max: 100, // Limit each IP to 100 requests
  windowMs: 60 * 60 * 1000, // Per hour
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api/', limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', validateUserInput, (req, res) => {
  try {
    // In a real application, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    // Filter based on query parameters (if any)
    const filteredUsers = users.filter(user => {
      // Safe filtering - only allow specific fields
      if (req.query.name) {
        return user.name.toLowerCase().includes(req.query.name.toLowerCase());
      }
      if (req.query.email) {
        return user.email.toLowerCase().includes(req.query.email.toLowerCase());
      }
      return true;
    });

    res.json({
      status: 'success',
      results: filteredUsers.length,
      data: { users: filteredUsers }
    });
  } catch (err) {
    // Pass error to global error handler
    next(err);
  }
});

// Specific user endpoint with ID validation
app.get('/users/:id', validateUserInput, (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // Validate ID is a positive integer
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        status: 'fail',
        message: 'Invalid user ID. Must be a positive integer.'
      });
    }

    // In a real application, fetch from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        status: 'fail',
        message: 'User not found'
      });
    }

    res.json({
      status: 'success',
      data: { user }
    });
  } catch (err) {
    next(err);
  }
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use(globalErrorHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

// Input validation middleware
const { body, param, query, validationResult } = require('express-validator');

// Validate user input for user-related endpoints
const validateUserInput = [
  // Validate query parameters
  query('name')
    .optional()
    .isString()
    .trim()
    .escape()
    .isLength({ max: 50 })
    .withMessage('Name must be a string with maximum 50 characters'),

  query('email')
    .optional()
    .isString()
    .trim()
    .isEmail()
    .withMessage('Please provide a valid email address')
    .normalizeEmail(),

  // Validate route parameters
  param('id')
    .optional()
    .isInt({ gt: 0 })
    .withMessage('ID must be a positive integer'),

  // Process validation results
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'fail',
        errors: errors.array().map(err => ({
          field: err.param,
          message: err.msg
        }))
      });
    }
    next();
  }
];

module.exports = { validateUserInput };

// Custom Error Class for standardized error handling
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);

    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    // Capture stack trace, excluding this constructor
    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;

// Global Error Handling Middleware
const AppError = require('../utils/appError');

const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });

    // Programming or other unknown error: don't leak error details
  } else {
    // Log error for developers
    console.error('ERROR 💥', err);

    res.status(500).json({
      status: 'error',
      message: 'Something went wrong!'
    });
  }
};

module.exports = (err, req, res, next) => {
  // Set defaults
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Determine environment
  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else {
    let error = { ...err };
    // Handle specific error types
    if (error.name === 'CastError') error = handleCastErrorDB(error);
    if (error.code === 11000) error = handleDuplicateFieldsDB(error);
    if (error.name === 'ValidationError') error = handleValidationErrorDB(error);

    sendErrorProd(error, res);
  }
};

// Helper functions for specific error types
const handleCastErrorDB = err => {
  const message = `Invalid ${err.path}: ${err.value}.`;
  return new AppError(message, 400);
};

const handleDuplicateFieldsDB = err => {
  const value = err.errmsg.match(/(["'])(\\?.)*?\1/)[0];
  const message = `Duplicate field value: ${value}. Please use another value!`;
  return new AppError(message, 400);
};

const handleValidationErrorDB = err => {
  const errors = Object.values(err.errors).map(el => el.message);
  const message = `Invalid input data. ${errors.join('. ')}`;
  return new AppError(message, 400);
};

