// Improved application with error handling, input validation, and security best practices

const express = require('express');
const app = express();

// Security middleware
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Body parser
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Security headers
app.use(helmet());
// Prevent parameter pollution
app.use(hpp());
// Data sanitization against XSS
app.use(xss());
// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// CORS (if needed)
// const cors = require('cors');
// app.use(cors());

// Request logging
app.use((req, res, next) => {
  console.log(`${req.method} ${req.path} - ${new Date().toISOString()}`);
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const { detailed } = req.query;

    // Sanitize boolean parameter
    const isDetailed = detailed === 'true' || detailed === '1';

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
    };

    if (isDetailed) {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString(),
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Parse and validate numeric parameters
    const parsedLimit = Math.min(parseInt(limit) || 10, 100); // Max 100
    const parsedOffset = Math.max(parseInt(offset) || 0, 0); // Min 0

    // Validate search parameter (if provided)
    let parsedSearch = '';
    if (search) {
      parsedSearch = String(search).trim().substring(0, 50); // Limit length
    }

    // Sample data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Filter users based on search (if provided)
    let filteredUsers = users;
    if (parsedSearch) {
      const searchLower = parsedSearch.toLowerCase();
      filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(
      parsedOffset,
      parsedOffset + parsedLimit
    );

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: filteredUsers.length,
        hasMore: parsedOffset + parsedLimit < filteredUsers.length
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      status: 'error',
      message: 'Internal server error',
      timestamp: new Date().toISOString(),
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: 'Route not found',
    timestamp: new Date().toISOString(),
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Don't leak stack trace in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    status: 'error',
    message: err.message || 'Internal server error',
    ...(!isProduction && { stack: err.stack }), // Only include stack in dev
    timestamp: new Date().toISOString(),
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

