// Secure application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded data
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const { detailed } = req.query;

    // Input validation for query parameters
    if (detailed !== undefined && typeof detailed !== 'string') {
      return res.status(400).json({
        error: 'Invalid query parameter',
        message: 'detailed parameter must be a string if provided'
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      ...(detailed === 'true' && { 
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage() 
      })
    };

    res.json(response);
  } catch (error) {
    // Centralized error handling
    handleError(res, error, 'Health check failed');
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Input validation
    const validationErrors = [];

    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        validationErrors.push('limit must be a positive integer between 1 and 100');
      }
    }

    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        validationErrors.push('offset must be a non-negative integer');
      }
    }

    if (search !== undefined && (typeof search !== 'string' || search.length > 50)) {
      validationErrors.push('search must be a string with maximum length of 50 characters');
    }

    if (validationErrors.length > 0) {
      return res.status(400).json({
        error: 'Validation failed',
        details: validationErrors
      });
    }

    // Simulated user data with pagination and search
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      const searchTerm = search.toLowerCase().trim();
      filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const limitNum = limit ? parseInt(limit, 10) : 10;
    const offsetNum = offset ? parseInt(offset, 10) : 0;
    const paginatedUsers = filteredUsers.slice(offsetNum, offsetNum + limitNum);

    res.json({
      count: filteredUsers.length,
      limit: limitNum,
      offset: offsetNum,
      users: paginatedUsers
    });
  } catch (error) {
    handleError(res, error, 'Failed to retrieve users');
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  handleError(res, error, 'Internal server error');
});

// Helper function for consistent error responses
function handleError(res, error, message = 'An error occurred') {
  console.error(`${message}:`, error); // Log for internal monitoring

  // Don't leak stack traces or internal details in production
  const response = {
    error: message
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = error.stack;
    response.details = error.message;
  }

  // Determine appropriate status code
  let statusCode = 500;
  if (error.type === 'entity.too.large') {
    statusCode = 413; // Payload too large
  } else if (error.status) {
    statusCode = error.status; // Use custom status if provided
  }

  res.status(statusCode).json(response);
}

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

