// Enhanced application with improved error handling, input validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const AppError = require('./utils/appError');
const globalErrorHandler = require('./controllers/errorController');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS for all origins (adjust as needed)

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});
app.use('/api/', limiter);

// Body parser, reading data from body into req.body
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Data sanitization against XSS
app.use(xss());

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Prevent parameter pollution
app.use(hpp({
  whitelist: ['duration', 'ratingsQuantity', 'ratingsAverage', 'difficulty', 'price']
}));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with improved error handling
app.get('/users', async (req, res, next) => {
  try {
    // Input validation for query parameters
    const { limit, offset } = req.query;

    // Validate limit and offset are numbers
    if (limit !== undefined && (isNaN(parseInt(limit)) || parseInt(limit) <= 0)) {
      return next(new AppError('Limit must be a positive number', 400));
    }

    if (offset !== undefined && (isNaN(parseInt(offset)) || parseInt(offset) < 0)) {
      return next(new AppError('Offset must be a non-negative number', 400));
    }

    // Mock data - in real app, this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply pagination if provided
    const parsedLimit = limit ? parseInt(limit) : users.length;
    const parsedOffset = offset ? parseInt(offset) : 0;

    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      status: 'success',
      results: paginatedUsers.length,
      data: {
        users: paginatedUsers
      }
    });
  } catch (err) {
    next(err); // Pass error to error handling middleware
  }
});

// Handle undefined routes
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// Global error handling middleware
app.use(globalErrorHandler);

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);

    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = AppError;

// Global error handling controller
const sendErrorDev = (err, res) => {
  res.status(err.statusCode).json({
    status: err.status,
    error: err,
    message: err.message,
    stack: err.stack
  });
};

const sendErrorProd = (err, res) => {
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });

    // Programming or other unknown error: don't leak error details
  } else {
    // Log error for developers
    console.error('ERROR 💥', err);

    // Send generic message
    res.status(500).json({
      status: 'error',
      message: 'Something went very wrong!'
    });
  }
};

module.exports = (err, req, res, next) => {
  // Set defaults
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Send error based on environment
  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(err, res);
  } else if (process.env.NODE_ENV === 'production') {
    let error = { ...err };
    error.message = err.message;

    sendErrorProd(error, res);
  }
};

const request = require('supertest');
const app = require('./app');

describe('API Endpoints', () => {
  describe('GET /health', () => {
    it('should return server status', async () => {
      const res = await request(app).get('/health');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toHaveProperty('status', 'ok');
    });
  });

  describe('GET /users', () => {
    it('should return users list', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toHaveProperty('status', 'success');
      expect(res.body.data.users).toBeInstanceOf(Array);
    });

    it('should validate limit parameter', async () => {
      const res = await request(app).get('/users?limit=-1');
      expect(res.statusCode).toEqual(400);
      expect(res.body).toHaveProperty('status', 'fail');
    });

    it('should validate offset parameter', async () => {
      const res = await request(app).get('/users?offset=-5');
      expect(res.statusCode).toEqual(400);
      expect(res.body).toHaveProperty('status', 'fail');
    });

    it('should paginate results correctly', async () => {
      const res = await request(app).get('/users?limit=1&offset=1');
      expect(res.statusCode).toEqual(200);
      expect(res.body.data.users).toHaveLength(1);
    });
  });

  describe('Error Handling', () => {
