// Focus on security best practices

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Middleware
app.use(express.json());
app.use(helmet()); // Security headers
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Sanitize data to prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging for security monitoring
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Custom error classes for better error handling
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
    this.name = 'ValidationError';
  }
}

// Async error wrapper utility
const catchAsync = (fn) => {
  return (req, res, next) => {
    fn(req, res, next).catch(next);
  };
};

// Validation middleware examples (for future route expansion)
const validateUserId = (req, res, next) => {
  const userId = parseInt(req.params.id);
  if (isNaN(userId) || userId <= 0) {
    return next(new ValidationError('Invalid user ID'));
  }
  req.validatedUserId = userId;
  next();
};

const validatePagination = (req, res, next) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  if (page < 1 || limit < 1 || limit > 100) {
    return next(new ValidationError('Invalid pagination parameters'));
  }

  req.query.page = page;
  req.query.limit = limit;
  next();
};

// Routes with improved error handling
app.get('/health', catchAsync(async (req, res) => {
  // Simulate potential async operation
  const status = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  };

  res.json(status);
}));

app.get('/users', catchAsync(async (req, res) => {
  // In a real app, this would come from a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Example of using query parameters with validation
  const { page = 1, limit = 10 } = req.query;
  const start = (page - 1) * limit;
  const end = start + parseInt(limit);

  res.json({
    data: users.slice(start, end),
    pagination: {
      page: parseInt(page),
      limit: parseInt(limit),
      total: users.length
    }
  });
}));

// Example route demonstrating input validation
app.get('/users/:id', validateUserId, catchAsync(async (req, res) => {
  // In a real app, fetch user from database using req.validatedUserId
  const user = { id: req.validatedUserId, name: 'Sample User', email: 'user@example.com' };

  if (!user) {
    return next(new AppError('User not found', 404));
  }

  res.json({ data: user });
}));

// 404 handler
app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404)));
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Set default values
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error for monitoring (in production, use proper logging service)
  console.error(`${new Date().toISOString()} - Error:`, {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    ip: req.ip,
    method: req.method
  });

  // Send error response
  res.status(err.statusCode).json({
    status: err.status,
    message: err.isOperational ? err.message : 'Something went wrong!',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

