// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent MongoDB injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset, search } = req.query;

    // Input validation and sanitization
    const parsedLimit = parseInt(limit) || 10;
    const parsedOffset = parseInt(offset) || 0;

    if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Limit must be a number between 1 and 100'
      });
    }

    if (isNaN(parsedOffset) || parsedOffset < 0) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Offset must be a non-negative number'
      });
    }

    // Simulate user data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search && typeof search === 'string') {
      // Sanitize search input
      const sanitizedSearch = search.trim().substring(0, 50); // Limit length
      if (sanitizedSearch) {
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
          user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
        );
      }
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      count: filteredUsers.length,
      limit: parsedLimit,
      offset: parsedOffset,
      users: paginatedUsers
    });

  } catch (error) {
    // Centralized error handling
    console.error('Error in /users endpoint:', error);

    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : 'Bad request',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong',
    // Only include stack trace in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Graceful shutdown
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

