// Improved application with better error handling, input validation, and security

const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Input validation helper functions
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const validateId = (id) => {
  return !isNaN(id) && parseInt(id) > 0;
};

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    if (Object.keys(req.query).length > 0) {
      // Basic query parameter validation
      for (const key in req.query) {
        if (!/^[a-zA-Z0-9_-]+$/.test(key)) {
          return res.status(400).json({
            error: 'Bad Request',
            message: 'Invalid query parameter name'
          });
        }
      }
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal Server Error',
      message: process.env.NODE_ENV === 'development' ? error.message : 'Something went wrong'
    });
  }
});

// Users endpoint with improved validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const filters = {};

    if (req.query.id) {
      if (!validateId(req.query.id)) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Invalid user ID format'
        });
      }
      filters.id = parseInt(req.query.id);
    }

    if (req.query.name) {
      // Sanitize name input (basic example)
      const cleanName = req.query.name.trim().replace(/[<>]/g, '');
      if (cleanName.length < 1 || cleanName.length > 50) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Name must be between 1 and 50 characters'
        });
      }
      filters.name = cleanName;
    }

    // In a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filters
    let filteredUsers = users;
    if (filters.id) {
      filteredUsers = filteredUsers.filter(user => user.id === filters.id);
    }
    if (filters.name) {
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(filters.name.toLowerCase())
      );
    }

    res.json({
      count: filteredUsers.length,
      data: filteredUsers
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal Server Error',
      message: process.env.NODE_ENV === 'development' ? error.message : 'Something went wrong'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Default error status
  const statusCode = err.status || 500;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Something went wrong',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

