    // Invalid ID (non-numeric)
    response = await request(app).get('/users?id=abc');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Bad Request');

    // Invalid ID (zero)
    response = await request(app).get('/users?id=0');
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Bad Request');
  });

  test('should sanitize and validate name parameter', async () => {
    // Valid name
    let response = await request(app).get('/users?name=Ali');
    expect(response.status).toBe(200);

    // Name with potential XSS
    response = await request(app).get('/users?name=<script>alert(1)</script>');
    expect(response.status).toBe(200); // Should be sanitized

    // Too long name
    response = await request(app).get('/users?name=' + 'a'.repeat(51));
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error', 'Bad Request');
  });
});

describe('Error Handling', () => {
  test('should handle 404 for undefined routes', async () => {
    const response = await request(app).get('/undefined-route');
    expect(response.status).toBe(404);
    expect(response.body).toHaveProperty('error', 'Not Found');
  });

  test('should handle internal errors gracefully', async () => {
    // This test would require mocking an internal error
    // In a real app, you might test database connection failures, etc.
    const response = await request(app).get('/health');
    expect(response.status).toBe(200); // Should still work normally
  });
});

describe('Rate Limiting', () => {
  test('should implement rate limiting', async () => {
    // Make multiple requests quickly
    const promises = [];
    for (let i = 0; i < 5; i++) {
      promises.push(request(app).get('/health'));
    }

    const responses = await Promise.all(promises);
    // All should succeed since we're well under the limit
    responses.forEach(response => {
      expect(response.status).toBe(200);
    });
  });
});

