// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Initialize Express app
const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL-encoded bodies
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiter to all requests
app.use(limiter);

// Custom middleware for logging and request validation
app.use((req, res, next) => {
  // Log incoming requests for monitoring
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} from ${req.ip}`);

  // Basic input validation for query parameters
  if (Object.keys(req.query).length > 0) {
    for (const [key, value] of Object.entries(req.query)) {
      // Check for potentially malicious input patterns
      if (typeof value === 'string') {
        // Basic XSS attempt detection
        const xssPatterns = [
          /<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi,
          /javascript:/i,
          /on\w+\s*=/i,
          /<iframe/i,
          /<img/i,
          /<svg/i,
          /onload\s*=/i
        ];

        for (const pattern of xssPatterns) {
          if (pattern.test(value)) {
            console.warn(`Potential XSS attempt detected in query param ${key}: ${value}`);
            return res.status(400).json({
              error: 'Bad Request',
              message: 'Invalid input detected'
            });
          }
        }
      }
    }
  }

  next();
});

// Health check endpoint with improved error handling
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage()
    };

    res.status(200).json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve health status'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any are provided
    const { limit, offset, search } = req.query;

    // Sample user data (in a real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Validate limit parameter
    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum <= 0 || limitNum > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Limit must be a positive integer between 1 and 100'
        });
      }
    }

    // Validate offset parameter
    if (offset !== undefined) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Offset must be a non-negative integer'
        });
      }
    }

    // Apply pagination
    let filteredUsers = [...users];

    // Apply search filter if provided
    if (search) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Search must be a string with maximum length of 50 characters'
        });
      }

      const searchLower = search.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const limitNum = limit ? parseInt(limit, 10) : filteredUsers.length;
    const offsetNum = offset ? parseInt(offset, 10) : 0;

    const paginatedUsers = filteredUsers.slice(offsetNum, offsetNum + limitNum);

    res.status(200).json({
      count: paginatedUsers.length,
      total: filteredUsers.length,
      limit: limitNum,
      offset: offsetNum,
      users: paginatedUsers
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: err.message || 'An error occurred'
  };

  // In development, include stack trace
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception thrown:', error);
  process.exit(1);
});

module.exports = app;

